SELECT * FROM service_member
WHERE service_type = #{serviceType}
AND status = 1

AND store_id = #{storeId}

ORDER BY rating DESC, total_tasks ASC

SELECT (
    (SELECT COUNT(*) FROM door_cleaning_appointment
     WHERE member_id = #{memberId} AND DATE(COALESCE(appointment_date, date)) = #{date}
     AND status IN ('pending', 'confirmed'))
    +
    (SELECT COUNT(*) FROM grooming_appointments
     WHERE member_id = #{memberId} AND date = #{date}
     AND status IN ('pending', 'confirmed'))
    +
    (SELECT COUNT(*) FROM hospital_appointments
     WHERE member_id = #{memberId} AND date = #{date}
     AND status IN ('pending', 'confirmed'))
) AS cnt

SELECT * FROM service_member
WHERE user_id = #{userId}
LIMIT 1

SELECT COUNT(*) FROM door_cleaning_appointment
WHERE member_id = #{memberId} AND DATE(COALESCE(appointment_date, date)) = #{date}
AND status IN ('pending', 'confirmed')

SELECT COUNT(*) FROM grooming_appointments
WHERE member_id = #{memberId} AND date = #{date}
AND status IN ('pending', 'confirmed')

SELECT COUNT(*) FROM hospital_appointments
WHERE member_id = #{memberId} AND date = #{date}
AND status IN ('pending', 'confirmed')
